window.AK_ASSETS={};
window.AK_PROJECTS=[{"id": "diom", "title": "ДИОМ", "category": "Айдентика · Брендбук · Motion", "kind": "Реальный проект", "lead": "Одна система. От знака до городской среды.", "accent": "#ff5f27", "bg": "#e9e9e9", "fg": "#222222", "palette": ["#ff5f27", "#242424", "#6fb0b6", "#f4f4f4"], "role": "Разработка фирменного стиля и брендбука. Визуальная концепция, типографика и система носителей.", "scope": "Брендбук, digital, документация, навигационные и предметные носители.", "idea": "Образ организации складывается не из отдельного логотипа. Он проявляется в десятках ежедневных контактов: на экране, в документе, на пропуске и на объекте. Задача — связать эти точки общим визуальным языком.", "chapters": [{"title": "01 — От строительной формы к знаку", "text": "В основе фирменной графики — геометрический объём и последовательность модулей. Знак отсылает к строительству и инфраструктуре, оставаясь достаточно простым для небольшого бейджа и крупного цифрового экрана. В брендбуке показаны исходный и обновлённый варианты, построение и цветовые решения."}, {"title": "02 — Характер в типографике", "text": "Заголовочный Bounded задаёт плотность и узнаваемость крупных сообщений. PT Root UI отвечает за длинные тексты и интерфейсные задачи. Эта пара позволяет разделять эмоциональный акцент и повседневное чтение, не теряя единства системы."}, {"title": "03 — Цвет как рабочий инструмент", "text": "Оранжевый создаёт точку внимания. Графит организует контраст, светлые фоны дают место информации, бирюзовый расширяет палитру. Цвета используются в разных пропорциях: от спокойного делового документа до яркой ленты пропуска."}, {"title": "04 — Система в действии", "text": "Принципы развиваются в документах, визитках, папках, бейджах, календарях и сувенирной продукции. На каждом носителе меняется масштаб и композиция, но сохраняются знак, шрифтовой характер и логика акцентов."}, {"title": "05 — От макета к предмету", "text": "Интерактивный просмотр ниже переводит пропуск в объём: лицевая сторона взята из брендбука, варианты лент повторяют его цветовые решения. Оборотная сторона — отдельная адаптация для этой презентации. Вращение позволяет оценить пропорции, контраст и поведение графики в пространстве."}, {"title": "06 — Единые правила для команды", "text": "Итоговый брендбук содержит 32 страницы и служит основой для последовательного применения айдентики. Здесь доступен весь документ, а не только обложки. Изображения продукции в нём представлены как проектные макеты: наличие визуализации не означает изготовление носителя."}], "images": ["assets/brandbook/page-08.jpg", "assets/brandbook/page-15.jpg"], "demo": "badge"}, {"id": "alpakoff", "title": "ALPAKOFF", "category": "Бренд · Упаковка · E-commerce", "kind": "Собственный бизнес / концепция редизайна", "lead": "Цветы как часть пространства.", "accent": "#daa3a5", "bg": "#f7f7f5", "fg": "#111111", "palette": ["#000000", "#ffffff", "#daa3a5", "#525252"], "role": "Владелец ALPAKOFF с 2020 года. Развитие бизнеса, маркетинг, продажи, ассортимент и работа с партнёрами. В кейсе — действующий магазин и концепция дальнейшего развития бренда.", "scope": "Оригинальный логотип ALPAKOFF, фирменная палитра, арт-дирекшн, концепция упаковки и интернет-магазина.", "idea": "ALPAKOFF — мой бизнес в сфере искусственных цветов, растений и интерьерных решений. Я рассматриваю его одновременно как продукт, сервис и визуальную систему: от того, как покупатель знакомится с ассортиментом, до того, как выбранная композиция живёт в интерьере.", "chapters": [{"title": "Бизнес, который я развиваю сам", "text": "ALPAKOFF объединяет розничные покупки, оптовые заказы и сотрудничество с дизайнерами. Моя роль выходит за рамки визуального оформления: я работаю с ассортиментом, маркетингом, продажами, поставщиками и ежедневной организацией бизнеса. Этот опыт помогает принимать дизайн-решения с пониманием того, как они отражаются на выборе покупателя и работе магазина."}, {"title": "Не букет на один день, а часть интерьера", "text": "Искусственные цветы выбирают для дома, ресторанов, витрин и событий. В каждом сценарии важны свои свойства: размер и оттенок, возможность собрать несколько стеблей в композицию, повторить оформление или вписать предмет в готовую среду. Визуальная подача должна показывать не только отдельный цветок, но и его масштаб, фактуру, сочетания и характер света."}, {"title": "Узнаваемость начинается со знака", "text": "Исходный логотип ALPAKOFF сохранён: геометрическое начертание, широкая пропорция и характерный разделитель перед OFF. Чёрный и белый задают структуру, розовый #DAA3A5 добавляет мягкий акцент. Новая подача опирается на действующий бренд. Реальные фотографии с сайта показывают продукт, а концептуальные сцены упаковки демонстрируют направление развития."}, {"title": "Упаковка и момент знакомства", "text": "В концепции упаковки матовый чёрный короб сочетается с тишью, розовой биркой и карточкой ухода. Важно не только первое впечатление: упаковка должна удерживать форму композиции, защищать детали и помогать покупателю аккуратно распаковать заказ. Изображения упаковки — проектное предложение; конструкция требует прототипирования и проверки перед производством."}, {"title": "Каталог с понятной логикой", "text": "Действующий магазин разделяет ассортимент на цветущие растения, зелень, ампельные растения, деревья, кусты и другие категории. Для дальнейшего развития предлагаю дополнительный вход через сценарий: один акцент для дома, оформление коммерческого пространства, подборка для события. Это дополняет привычный товарный каталог и помогает начать выбор с задачи."}, {"title": "Партнёрство с дизайнерами", "text": "На сайте выделено направление сотрудничества с дизайнерами. Для этой аудитории магазин становится источником решений под конкретный проект. В развитии сервиса я бы усилил подборки по палитре и масштабу, примеры размещения и понятный способ обсудить состав заказа. Такие материалы помогают связать эстетическую идею с подбором реальных позиций."}, {"title": "Фотография как часть сервиса", "text": "Визуальная история соединяет живые фотографии из каталога ALPAKOFF и предметные сцены нового направления бренда. Полный кадр сохраняет пластику позы, характер света и масштаб цветка. Фотографии работают как часть общей композиции, а не как набор отдельных товарных карточек."}, {"title": "От визуального образа до работы магазина", "text": "Мой предпринимательский опыт связывает дизайн с повседневными задачами: поддерживать ассортимент, объяснять покупателю различия, организовывать продажи и взаимодействовать с поставщиками. Здесь показаны действующий бренд, реальный магазин и продуманное направление его дальнейшего развития."}], "images": ["assets/alpakoff-hero-v6.webp", "assets/alpakoff-2.webp"], "demo": "shop", "gallery": [{"image": "assets/alpakoff-editorial-13.webp", "title": "Сакура / Нежно-розовый", "source": "https://static.tildacdn.com/stor6436-3563-4564-a537-616533383761/41475420.jpg"}, {"image": "assets/alpakoff-editorial-16.webp", "title": "Пион / Сиреневый", "source": "https://static.tildacdn.com/stor3863-3666-4433-a333-626333653334/47056652.jpg"}]}, {"id": "burrow", "title": "BURROW", "category": "Архитектура · Айдентика · Digital", "kind": "Архитектурное бюро / концепция", "lead": "Архитектура с характером.", "accent": "#2447e8", "bg": "#2447e8", "fg": "#ffffff", "palette": ["#2447e8", "#eeece6", "#282a28", "#bfc6c2"], "role": "Арт-дирекшн, концепция и дизайн.", "scope": "Айдентика, сайт, печать, офис и экспозиция.", "idea": "Строгая геометрия. Мягкие границы. Пространство, которое чувствуют.", "chapters": [], "images": ["assets/burrow/print.webp", "assets/burrow/pavilion.webp"]}, {"id": "kitit", "title": "KITit", "category": "Айдентика · Digital · Среда", "kind": "Концепция digital-агентства", "lead": "Собираем сильное вместе.", "accent": "#e52c32", "bg": "#e52c32", "fg": "#ffffff", "palette": ["#e52c32", "#ffd83d", "#f5f2ea", "#252522"], "role": "Арт-дирекшн, айдентика, UX/UI, концепция среды.", "scope": "Бренд, сайт, коммуникации, носители и офис.", "idea": "Серьёзно к делу. Легко в общении.", "chapters": [], "images": ["assets/kitit/cover.webp", "assets/kitit/kit-photo.webp"]}, {"id": "vektor", "title": "VEKTOR", "category": "Automotive · Айдентика · Digital", "kind": "Независимый концепт", "lead": "Двигаться в своём ритме.", "accent": "#ef482c", "bg": "#e9e7e1", "fg": "#171819", "palette": ["#171819", "#e9e7e1", "#ef482c", "#9eafa9"], "role": "Автор концепции: стратегия, арт-дирекшн, визуальная система и интерфейс.", "scope": "Позиционирование · Айдентика · Продуктовый сайт · Выбор отделки", "idea": "Независимая концепция автомобильного бренда и его цифрового пространства. В центре — не абстрактная технология, а повседневная жизнь человека: город, личный ритм и удовольствие от продуманной вещи.", "chapters": [{"title": "Задача", "text": "Превратить знакомство с новым автомобильным брендом в последовательный выбор. Посетителю важно сначала почувствовать характер машины, затем понять её устройство и увидеть детали, которые делают её своей."}, {"title": "Позиционирование", "text": "VEKTOR — вымышленный бренд городского электромобиля. Его характер складывается из спокойной уверенности, лаконичной формы и внимания к ощущениям. Визуальная концепция исследует этот образ, не заявляя готовую инженерную модель."}, {"title": "Айдентика", "text": "Широкий словесный знак, графит, минеральный светлый фон и красно-оранжевый акцент. Горизонталь световой линии автомобиля продолжается в навигации сайта, делении разделов и тонких элементах фирменной графики."}, {"title": "Арт-дирекшн", "text": "Бетон и направленный свет раскрывают силуэт снаружи. Тёплая ткань и шлифованный металл показывают тактильность внутри. Контраст общего плана и близкой детали задаёт ритм всей истории."}, {"title": "Пользовательский сценарий", "text": "От первого впечатления — к экстерьеру, интерьеру и выбору материала. Переключатели меняют изображение и сопровождающий текст, а выбор отделки сохраняется при рассмотрении других частей концепции."}, {"title": "Границы концепции", "text": "Разработаны визуальная система, архитектура страницы, демонстрационный выбор отделки и адаптивная версия. Автомобильные изображения созданы для проекта с ИИ. Технические характеристики, цены и результаты продаж не выдумываются."}], "images": ["assets/vektor-exterior.webp", "assets/vektor-interior.webp"], "demo": "vektor"}, {"id": "pulp", "title": "PULP", "category": "Напитки · Упаковка · 3D · Сайт", "kind": "Независимый концепт", "lead": "Вкус имеет форму.", "accent": "#db8044", "bg": "#f1e1d0", "fg": "#271d18", "palette": ["#db8044", "#f1e1d0", "#271d18", "#c5c5c0"], "role": "Автор концепции: стратегия, арт-дирекшн, визуальная система и интерфейс.", "scope": "Напитки · Упаковка · 3D · Сайт", "idea": "Независимая концепция бренда напитков. Один выразительный логотип, три вкусовых цвета и алюминиевая банка, которую можно рассмотреть со всех сторон.", "chapters": [{"title": "Идея бренда", "text": "PULP — вымышленный бренд напитков с выразительной фруктовой палитрой. Концепция строится вокруг простого ритуала: выбрать настроение, открыть банку, сделать паузу."}, {"title": "Вкусовая система", "text": "Абрикос, вишня и юдзу получили собственные цветовые коды. Вертикальная типографика объединяет линейку, а название вкуса остаётся на привычном месте."}, {"title": "Материал и упаковка", "text": "На поверхности банки сочетаются печать и открытый алюминий. Металлические кромки, закаточный шов и верхнее кольцо создают узнаваемый предметный силуэт."}, {"title": "Сайт как знакомство с продуктом", "text": "Выбор вкуса меняет цвет, название и описание в одной сцене. Вращение позволяет оценить пропорции банки и расположение графики. Это демонстрационный интерфейс, без оформления заказа и заявлений о составе продукта."}], "images": ["assets/pulp-1.webp", "assets/pulp-1.webp"], "demo": "pulp"}, {"id": "school-builder", "title": "School Builder", "category": "Игра · 3D · Образовательная среда", "kind": "Реальный проект / Концепция развития айдентики", "lead": "Школа начинается с твоего решения.", "accent": "#ff6b3b", "bg": "#e5e1dc", "fg": "#212224", "palette": ["#ff6b3b", "#212224", "#3ba8af", "#e5e1dc"], "role": "Разработка цифрового проекта. Концепция развития бренда игры.", "scope": "Механика · 3D-среда · Интерфейс · Брендбук", "idea": "Интерактивное знакомство с устройством школы через выбор и расстановку предметов.", "chapters": [], "images": ["assets/diom-elements/plane-a.webp", "assets/diom-elements/fakel-a.webp"], "demo": "school-builder"}, {"id": "osnova", "title": "ОСНОВА", "category": "Архитектура · Айдентика · Editorial", "kind": "Авторская концепция", "lead": "Не украшать архитектуру. Выявлять её логику.", "accent": "#c95532", "bg": "#e9e6de", "fg": "#282623", "palette": ["#c95532", "#282623", "#e9e6de", "#a7aaa5"], "role": "Концепция вымышленного архитектурного бюро.", "scope": "Словесный знак, композиционная система, монография, деловые носители, направление сайта.", "idea": "Бюро «ОСНОВА» задумано как практика, которая объясняет архитектуру через структуру, материал и повседневный опыт человека. Визуальная система использует язык рабочих материалов, доведённый до издательской точности.", "chapters": [{"title": "Структура вместо декоративного мотива", "text": "Базой становится пропорциональная сетка. Подписи, размеры, нумерация и крупные поля работают как инструменты ориентации. Знак не конкурирует с архитектурой: он обозначает авторство и собирает материалы в узнаваемую серию."}, {"title": "Материал и контраст", "text": "Тёплый минеральный оранжевый противопоставлен графиту, алюминию и бумаге. Тактильная палитра сохраняет связь с физическим строительством. Фотографическая подача подчёркивает плоскости, тени и масштаб, а не случайные декоративные предметы."}, {"title": "Из проекта — в издание", "text": "Монография организована как последовательность аргументов: контекст, принцип, чертёж, материал, пространство. Обложка, разделители и подписи используют одну систему, чтобы разные проекты бюро можно было собирать в общую библиотеку."}, {"title": "Цифровая витрина", "text": "Предлагаемая структура сайта начинается с портфеля работ. Внутри проекта — краткий тезис, планировочная идея, роль команды и материалы. Редакционная подача оставляет читателю место для внимательного просмотра."}, {"title": "Статус", "text": "Вымышленное бюро и самостоятельная концепция. Мокапы созданы с ИИ; строительство объектов, коммерческий заказ и реальные результаты не заявляются."}], "images": ["assets/osnova-1.webp", "assets/osnova-2.webp"], "demo": null}, {"id": "mono", "title": "MONO", "category": "Продукт · Упаковка · Web design", "kind": "Авторская концепция", "lead": "Всё лишнее — за пределами звука.", "accent": "#9babc1", "bg": "#f4f4f1", "fg": "#17191b", "palette": ["#17191b", "#bec4cb", "#f4f4f1", "#9babc1"], "role": "Дизайн-концепция вымышленного бренда акустики.", "scope": "Продуктовое направление, визуальная система, упаковка, интерактивная промостраница.", "idea": "MONO — концепция акустического устройства, в которой технология воспринимается через материал, пропорцию и тактильность. Сайт выстроен как спокойное знакомство с предметом: общий силуэт, деталь, конструкция, выбор.", "chapters": [{"title": "Один предмет — точный фокус", "text": "Главным героем остаётся устройство. Металл, акустическая ткань и мягкие переходы формы определяют визуальный язык. Типографика поддерживает продукт и не превращает страницу в каталог эффектов."}, {"title": "Демонстрация вместо обещаний", "text": "В концепции исследуются два варианта формы устройства и разные способы показа материала и конструкции. Второй кадр — отдельное дизайн-исследование, а не точная сборочная схема предмета из первого кадра. Характеристики мощности, времени работы и сертификации не выдумываются."}, {"title": "Мягкая последовательность", "text": "При переходе от общего вида к конструкции меняется масштаб. В интерактивном фрагменте можно переключить сценарий просмотра: форма, устройство, упаковка. Движение помогает сравнить детали и сохраняет непрерывность истории."}, {"title": "Тихая упаковка", "text": "Внешний короб поддерживает минимальный визуальный язык. Внутренняя организация должна последовательно знакомить с устройством и аксессуарами. Макет упаковки — направление для дальнейшей инженерной проработки, а не готовая производственная спецификация."}, {"title": "Статус", "text": "Вымышленный продукт. Предметные изображения созданы с ИИ, а промостраница разработана как работающий интерфейсный прототип. Покупка и доставка не предлагаются."}], "images": ["assets/mono-1.webp", "assets/mono-2.webp"], "demo": "mono"}, {"id": "ryadom", "title": "РЯДОМ", "category": "Социальный проект · Транспорт · Информация", "kind": "Авторская концепция", "lead": "Город становится ближе, когда его легче понять.", "accent": "#d64237", "bg": "#f3efe4", "fg": "#292724", "palette": ["#d64237", "#f3efe4", "#292724", "#cecbc3"], "role": "Независимая социальная концепция для транспортной среды.", "scope": "Плакаты, пассажирская памятка, карточка, система коротких сообщений.", "idea": "«Рядом» — идея коммуникации о внимании к другим пассажирам. Она переводит абстрактный призыв к заботе в понятные ситуации: оставить проход, предложить помощь, дать человеку время.", "chapters": [{"title": "Пассажир — в центре", "text": "Плакат должен считываться за короткий взгляд, а памятка — помогать в конкретной ситуации. Поэтому сообщение разделено на короткий заголовок, одно действие и пояснение. Смысл не должен зависеть только от цветового кода."}, {"title": "Ясная визуальная грамматика", "text": "Контрастный красный, светлый фон и крупный набор создают заметность в насыщенной транспортной среде. Условные графические элементы повторяют общую логику и не маскируются под официальную схему станций."}, {"title": "Одна тема — несколько дистанций", "text": "На стене работает крупный призыв. В раздаточном материале — последовательность действий. На небольшой карточке — одно напоминание. Меняется плотность информации, но сохраняются ритм, тон и визуальный характер."}, {"title": "Доступность требует проверки", "text": "Контраст, размер текста и понятность формулировок заложены как принципы проекта. Перед реальным внедрением нужны тесты с пассажирами, включая людей с различными ограничениями восприятия и мобильности. Соответствие нормативам здесь не заявляется."}, {"title": "Статус и авторство", "text": "Самостоятельная концепция, не официальный проект Московского метрополитена. Фирменный стиль метро и материалы других студий не приписываются автору портфолио. Показанные носители — новые ИИ-визуализации этой концепции."}], "images": ["assets/ryadom-1.webp", "assets/ryadom-2.webp"], "demo": null}, {"id": "pole", "title": "ПОЛЕ", "category": "FMCG · Айдентика · Упаковка", "kind": "Авторская концепция", "lead": "Хороший кофе. Ясный характер.", "accent": "#e2ab22", "bg": "#eae4d5", "fg": "#242019", "palette": ["#e2ab22", "#242019", "#eae4d5", "#998b6c"], "role": "Визуальная концепция вымышленного кофейного бренда.", "scope": "Словесный знак, упаковка, стаканы, транспортный короб, система товарной информации.", "idea": "ПОЛЕ — бренд, который говорит о кофе прямо. Он выделяется не сложной легендой, а уверенным именем, ясной упаковкой и последовательной подачей информации.", "chapters": [{"title": "Крупно — имя. Точно — детали", "text": "Словесный знак занимает собственную уверенную площадь. Сорт, способ приготовления и данные об обжарке получают постоянные позиции. В реальном продукте эти сведения должны заполняться подтверждёнными данными производителя."}, {"title": "Цвет, который узнают", "text": "Шафрановый цвет делает упаковку заметной на полке и в руках. Чёрный отвечает за читаемость и устойчивость композиции. Матовая бумага, крафт и металл создают предметный контекст без визуальной перегрузки."}, {"title": "От пакета до стакана", "text": "Система переносится на разные форматы за счёт пропорций и ритма текста. Пакет хранит подробную информацию, стакан работает на расстоянии, транспортный короб объединяет серию."}, {"title": "Практическая логика", "text": "Упаковка проектируется с учётом места для обязательной информации, маркировки партии и даты. Презентационные изображения показывают визуальное направление; финальная развёртка и производственные параметры требуют отдельной подготовки."}, {"title": "Статус", "text": "Вымышленный бренд и концептуальная упаковка. Изображения созданы с ИИ. Реальные продажи, производство и результаты рекламной кампании не заявляются."}], "images": ["assets/pole-1.webp", "assets/pole-2.webp"], "demo": null}, {"id": "sdvig", "title": "СДВИГ", "category": "Культура · Айдентика · Издательский дизайн", "kind": "Авторская концепция", "lead": "Новое искусство меняет точку зрения.", "accent": "#ccff44", "bg": "#153ac4", "fg": "#f4f4ee", "palette": ["#153ac4", "#ccff44", "#f4f4ee", "#141a2b"], "role": "Концепция вымышленной культурной институции.", "scope": "Афиши, выставочная графика, каталог, билет, правила поведения типографики.", "idea": "СДВИГ — пространство, в котором зрителю предлагают поменять привычную позицию. Идея переносится в графику через смещение масштаба, ритма и композиционного центра.", "chapters": [{"title": "Типографика как событие", "text": "Название становится главным материалом айдентики. Крупные буквы пересекают формат и меняют привычное соотношение фона и текста. При этом служебная информация получает отдельную стабильную зону."}, {"title": "Система, которая допускает различия", "text": "У каждой выставки может быть собственный визуальный материал. Объединяющими элементами остаются модульная сетка, цветовой контраст, структура заголовков и подписи. Айдентика поддерживает искусство, а не заменяет его."}, {"title": "От городской афиши к каталогу", "text": "Крупные носители работают через масштаб и контраст. В каталоге та же логика становится спокойнее: поля, ритм разворотов и выразительные разделители создают пространство для внимательного чтения."}, {"title": "Движение как правило", "text": "В цифровой версии текст смещается внутри заданных ограничений, сохраняя читаемость ключевого сообщения. Анимация начинается после появления блока и не мешает изучать подробности. Предусмотрен режим уменьшенного движения."}, {"title": "Статус", "text": "Самостоятельная концепция вымышленной институции. Изображения выставочного пространства и носителей созданы с ИИ; реальные выставки и заказчики не заявляются."}], "images": ["assets/sdvig-1.webp", "assets/sdvig-2.webp"], "demo": null}, {"id": "index-city", "title": "INDEX", "category": "Информационный дизайн · UX/UI · Data", "kind": "Авторская концепция", "lead": "Данные становятся понятными решениями.", "accent": "#3d66f5", "bg": "#111c32", "fg": "#eef2ff", "palette": ["#3d66f5", "#111c32", "#eef2ff", "#81a5df"], "role": "Концепция интерфейса для наблюдения за городскими проектами.", "scope": "Иерархия данных, состояния, таблица, фильтры, визуальные показатели и редакционная система отчёта.", "idea": "INDEX исследует, как руководитель может быстро понять состояние портфеля проектов, а затем перейти к деталям. Главный принцип — отделять ключевой сигнал от фоновой информации.", "chapters": [{"title": "Сначала вопрос", "text": "Что изменилось? Где нужна реакция? Какие данные требуют уточнения? Эти вопросы определяют структуру экрана. Краткий обзор помогает сориентироваться, а таблица сохраняет возможность точного сравнения."}, {"title": "Несколько уровней чтения", "text": "Крупные показатели, статусы и подробные строки имеют разный визуальный вес. Одинаковые состояния обозначаются последовательно, а цвет дублируется текстом. Интерфейс не требует запоминать значение каждого оттенка."}, {"title": "Интерактивный фрагмент", "text": "Ниже можно переключать состояние проектов и видеть соответствующие строки. Все значения демонстрационные. Это интерфейсная концепция, не действующая система мониторинга и не данные конкретной организации."}, {"title": "От экрана к отчёту", "text": "Печатная система повторяет иерархию продукта: короткий вывод, визуальная опора, детализация. Нумерация и подписи позволяют ссылаться на информацию без потери контекста."}, {"title": "Опыт, который лежит в основе", "text": "Направление связано с моей практикой цифровизации, подготовки аналитических материалов и внутренних инструментов. Однако сам INDEX — новый вымышленный продукт для портфолио; он не представлен как внедрённый сервис."}], "images": ["assets/index-1.webp", "assets/index-2.webp"], "demo": "index"}];
window.AK_DIOM_BOOK=[{"page": 1, "title": "Брендбук ДИОМ", "text": "Визуальная система Дирекции инфраструктуры образования Москвы. От знака и типографики до повседневных предметов.", "images": []}, {"page": 2, "title": "Эволюция знака", "text": "Объёмная композиция прежнего знака стала лаконичнее. Плоскостная графика лучше считывается на экране и в печати.", "images": ["assets/diom-elements/page-02-1.webp"]}, {"page": 3, "title": "Основной логотип", "text": "Геометрический знак и плотное начертание названия образуют основной фирменный блок.", "images": []}, {"page": 4, "title": "Модуль и варианты знака", "text": "Модуль задаёт геометрию, а варианты цвета позволяют использовать знак в разных контекстах.", "images": ["assets/diom-elements/page-04-detail-0.webp", "assets/diom-elements/page-04-detail-1.webp"]}, {"page": 5, "title": "Система компоновок", "text": "Горизонтальные, компактные и текстовые композиции сохраняют узнаваемость на разных форматах.", "images": []}, {"page": 6, "title": "Цвет и типографика", "text": "Bounded отвечает за заголовки. PT Root UI — за наборный текст. Оранжевый, графит и бирюзовый связывают носители в систему.", "images": []}, {"page": 7, "title": "Главная страница", "text": "Главная объединяет направления работы, проекты и сервисы Дирекции.", "images": ["assets/diom-elements/page-07-composition.webp"]}, {"page": 8, "title": "Визуальный язык сайта", "text": "Модульная сетка, контрастная типографика и архитектурные образы складываются в узнаваемую страницу.", "images": ["assets/diom-elements/page-08-1.webp", "assets/diom-elements/page-08-2.webp", "assets/diom-elements/page-08-3.webp", "assets/diom-elements/page-08-4.webp"]}, {"page": 9, "title": "Адаптивная система", "text": "Та же логика работает на компьютере, планшете и телефоне. На узком экране информация выстраивается в последовательный маршрут.", "images": ["assets/diom-elements/page-09-composition.webp"]}, {"page": 10, "title": "Digital в деталях", "text": "Информационные блоки и крупные изображения помогают ориентироваться в деятельности организации.", "images": ["assets/diom-elements/page-10-composition.webp"]}, {"page": 11, "title": "Изометрии школ ЦАО", "text": "Статичное и активное состояния изометрии. Цвет выделяет объект, сохраняя его архитектурную форму.", "images": ["assets/diom-elements/fakel-b.webp", "assets/diom-elements/fakel-a.webp"]}, {"page": 12, "title": "Школы реконструкции", "text": "Типовые школьные объекты получают собственные узнаваемые силуэты.", "images": ["assets/diom-elements/plane-b.webp", "assets/diom-elements/plane-a.webp"]}, {"page": 13, "title": "Экран и пространство", "text": "Айдентика сопровождает пользователя на экране и в физическом пространстве.", "images": ["assets/diom-elements/page-13-monitor.webp", "assets/diom-elements/page-13-1.webp"]}, {"page": 14, "title": "Корпоративный бейдж", "text": "Вертикальная типографика роли, имя, должность и фирменная лента. Ниже — объёмная адаптация для осмотра.", "images": ["assets/diom-elements/page-14-1.webp", "assets/diom-elements/page-14-2.webp"]}, {"page": 15, "title": "Деловая полиграфия", "text": "Бланки, конверты, визитки и предметы формируют деловую среду организации.", "images": ["assets/diom-elements/page-15-composition.webp"]}, {"page": 16, "title": "Визитные карточки", "text": "Варианты карточек: светлый, графитовый, оранжевый и бирюзовый.", "images": ["assets/diom-elements/page-16-composition.webp"]}, {"page": 17, "title": "Проектные документы", "text": "Фирменная система поддерживает структуру и читаемость проектной информации.", "images": ["assets/diom-elements/page-17-composition.webp"]}, {"page": 18, "title": "Бланки и коммуникация", "text": "Документация объединяет крупные заголовки, спокойный набор и акцентный цвет.", "images": ["assets/diom-elements/page-18-1.webp", "assets/diom-elements/page-18-2.webp", "assets/diom-elements/page-18-3.webp", "assets/diom-elements/page-18-4.webp", "assets/diom-elements/page-18-5.webp", "assets/diom-elements/page-18-6.webp"]}, {"page": 19, "title": "Благодарности и грамоты", "text": "Наградные документы сохраняют официальный характер и общий визуальный язык.", "images": ["assets/diom-elements/page-19-composition.webp"]}, {"page": 20, "title": "Карточки-пропуска", "text": "Два направления карточек: крупная типографика и модульная композиция знака.", "images": ["assets/diom-elements/page-20-1.webp", "assets/diom-elements/page-20-2.webp", "assets/diom-elements/page-20-3.webp", "assets/diom-elements/page-20-4.webp"]}, {"page": 21, "title": "Брелоки", "text": "Компактный носитель сохраняет контраст и читаемость фирменного блока.", "images": ["assets/diom-elements/page-21-1.webp", "assets/diom-elements/page-21-2.webp", "assets/diom-elements/page-21-3.webp"]}, {"page": 22, "title": "Пропуска на ретракторах", "text": "Ретрактор и карточка работают как единый комплект.", "images": ["assets/diom-elements/page-22-1.webp", "assets/diom-elements/page-22-2.webp"]}, {"page": 23, "title": "Рабочие носители", "text": "Защитная каска, сумка и календарь переносят айдентику в ежедневную работу.", "images": ["assets/diom-elements/page-23-1.webp", "assets/diom-elements/page-23-2.webp", "assets/diom-elements/page-23-3.webp", "assets/diom-elements/page-23-4.webp", "assets/diom-elements/page-23-5.webp"]}, {"page": 24, "title": "Знак в цифровой среде", "text": "Знак существует как предмет, иконка и часть экранной графики.", "images": ["assets/diom-elements/page-24-1.webp", "assets/diom-elements/page-24-2.webp", "assets/diom-elements/page-24-3.webp", "assets/diom-elements/page-24-4.webp"]}, {"page": 25, "title": "Стикеры", "text": "Стикеры развивают свободную сторону визуальной системы.", "images": ["assets/diom-elements/page-25-1.webp", "assets/diom-elements/page-25-2.webp", "assets/diom-elements/page-25-3.webp", "assets/diom-elements/page-25-4.webp", "assets/diom-elements/page-25-5.webp", "assets/diom-elements/page-25-6.webp"]}, {"page": 26, "title": "Мобильные аксессуары", "text": "Компактные элементы бренда на личных устройствах.", "images": ["assets/diom-elements/page-26-detail-0.webp", "assets/diom-elements/page-26-detail-1.webp"]}, {"page": 27, "title": "Упаковка стикеров", "text": "Прозрачная упаковка показывает сами элементы набора.", "images": ["assets/diom-elements/page-27-1.webp", "assets/diom-elements/page-27-2.webp"]}, {"page": 28, "title": "Блокноты", "text": "Разные форматы записей объединены типографикой и фирменной графикой.", "images": ["assets/diom-elements/page-28-1.webp", "assets/diom-elements/page-28-2.webp"]}, {"page": 29, "title": "Корпоративный транспорт", "text": "Крупный знак работает на масштабе автомобиля.", "images": ["assets/diom-elements/page-29-1.webp"]}, {"page": 30, "title": "Текстиль", "text": "Сдержанное размещение фирменного знака на одежде.", "images": ["assets/diom-elements/page-30-1.webp"]}, {"page": 31, "title": "Значки и аксессуары", "text": "Небольшие аксессуары дополняют систему предметных носителей.", "images": ["assets/diom-elements/page-31-1.webp", "assets/diom-elements/page-31-2.webp", "assets/diom-elements/page-31-3.webp", "assets/diom-elements/page-31-4.webp"]}, {"page": 32, "title": "Завершение системы", "text": "Знак, цвет и типографика соединяют все форматы в один образ.", "images": ["assets/diom-elements/page-32-composition.webp"]}];
