const cover=p=>p.id==='diom'?'assets/diom-cover.webp?v=2':p.images[0];const img=(src,alt,cls='',lazy=true)=>`<img src="${asset(src)}" alt="${alt}" class="${cls}" ${lazy?'loading="lazy"':''} width="1536" height="1024">`;
