function footer(){return `<footer id="contact"><div class="shell"><div class="footer-top"><span class="eyebrow">Контакт / Новые проекты</span><a href="${asset('assets/resume-designed.pdf')}" download="Artem-Krechetov-Resume.pdf">Резюме PDF ↓</a></div><h2>Есть задача?<br><em>Давайте обсудим.</em></h2><a class="email" href="mailto:temakre@yandex.ru">temakre@yandex.ru ↗︎</a><div class="footer-bottom"><span>© 2026 Артём Кречетов</span><a href="tel:+79990969564">+7 999 096-95-64</a><span>Бренды. Люди. Среда.</span></div></div></footer>`;}
function card(p,i){return `<a href="${href(p.id)}" class="project-card reveal project-${p.id}" style="--card-bg:${p.bg};--card-fg:${p.fg}"><div class="project-art">${img(cover(p),p.title+' — '+p.lead)}<span class="card-number">${String(i+1).padStart(2,'0')}</span><span class="card-enter" aria-hidden="true">↗︎</span></div><div class="card-caption"><h3>${p.title}</h3><span>${p.category}</span></div><p>${p.kind}</p></a>`;}
function home(){const featured=projects.find(p=>p.id==='alpakoff');return `<main class="studio-home"><section class="studio-intro shell"><div><span class="eyebrow">Артём Кречетов / Москва</span><h1 tabindex="-1">Креативный<br>директор<span class="accent-period">.</span></h1></div><div class="intro-author"><a class="intro-face" href="${href('about')}"><img src="${photo1}" alt="Артём Кречетов" width="110" height="132"></a><div><span class="eyebrow">Автор проектов</span><strong>Артём Кречетов</strong><p>Бренды, цифровые продукты<br>и образовательная среда.</p><div class="intro-author-links"><a href="${href('about')}">Обо мне ↗︎</a><a href="${asset('assets/resume-designed.pdf')}" download="Artem-Krechetov-Resume.pdf">Резюме ↓</a></div></div></div></section><section class="studio-stage shell"><div class="spotlight"><a id="spot-link" href="${href('alpakoff')}"><div class="spot-image">${img(featured.images[0],'ALPAKOFF — цветы и интерьерные решения','',false)}</div><div class="spot-caption"><div><span class="eyebrow">Избранный проект</span><h2 id="spot-title">${img('assets/alpakoff-logo.svg','ALPAKOFF','spot-brand',false)}</h2></div><span id="spot-category">Бренд · Упаковка · E-commerce</span><span class="spot-arrow">↗︎</span></div></a><div class="spotlight-meta"><span class="eyebrow"><span id="spot-count">01</span> / 04</span><div><button id="spot-prev" aria-label="Предыдущий проект">←</button><button id="spot-next" aria-label="Следующий проект">→</button><button id="spot-play" aria-pressed="false">Автопоказ</button></div></div></div><aside class="stage-index"><span class="eyebrow">Выбранные работы</span>${['alpakoff','diom','burrow','kitit','mono','sdvig'].map((id,i)=>{const p=projects.find(p=>p.id===id);return `<button class="stage-choice" data-feature="${i}" aria-pressed="${i===0}"><span>0${i+1}</span><div><strong>${p.title}</strong><small>${p.category}</small></div>${img(cover(p),'')}</button>`;}).join('')}<a class="index-all" href="${href('work')}">Все проекты <span>${projects.length} ↓</span></a><div class="stage-profile"><img src="${photo1}" alt="Артём Кречетов" width="100" height="120"><p>Дизайн, который<br>работает в жизни.<a href="${href('about')}">Обо мне ↗︎</a></p></div></aside></section><div class="name-band shell" aria-hidden="true">КРЕЧ<i class="nb-e">Е</i>ТОВ<span>®</span></div><div class="shell home-practice"><section class="practice"><div><span class="meta">Мой способ работать</span><h2 style="margin-top:22px">От первого вопроса<br>до последней детали.</h2><p>Сначала разбираюсь в задаче и контексте. Затем формулирую идею и собираю визуальную систему. Подключаю команду, распределяю ответственность и контролирую качество на каждом этапе.</p><p>Для меня одинаково важны характер решения и точность реализации — в интерфейсе, печати и физическом пространстве.</p><div class="tools"><span>Арт-дирекшн</span><span>Брендинг</span><span>UX/UI</span><span>Дизайн пространств</span><span>Figma</span><span>Tilda</span><span>HTML / CSS / JS</span><span>Bitrix24</span><span>Python</span><span>ИИ-инструменты</span></div></div>${photo(photo2,'02','Артём — вне рабочего кадра')}</section></div><section class="work shell" id="work"><div class="section-title"><h2>Выбранные работы<span>01—${projects.length}</span></h2><span class="eyebrow">Бренды / Digital / Среда</span></div><div class="work-grid">${projects.map(card).join('')}</div></section><section class="focus-story"><div class="shell focus-layout"><div><span class="eyebrow">ДИОМ / Визуальная система</span><h2 class="reveal">Один знак.<br>Десятки<br>применений.</h2><p>Айдентика городской институции: от сайта и документов до пропусков и предметов.</p><div><a class="text-link" href="${href('diom')}">Изучить кейс ↗︎</a><a class="text-link" href="${href('book')}">Брендбук / 32 страницы ↗︎</a></div></div><a class="focus-visual" href="${href('diom')}">${img('assets/brandbook/page-14.jpg','Пропуска и ленты ДИОМ')}<span>Интерактивные пропуска / 360° ↗︎</span></a></div></section><section class="about-teaser shell"><div class="teaser-portrait">${img('assets/personal.webp','Артём Кречетов')}</div><div><span class="eyebrow">Дизайнер. Руководитель. Предприниматель.</span><h2>За каждой системой —<br>человек.</h2><p>Руководил дизайн-командой, развиваю собственный бизнес и создаю цифровые решения для образовательной инфраструктуры Москвы.</p><a class="text-link" href="${href('about')}">Опыт, подход и резюме ↗︎</a></div></section></main>${footer()}`;}
function palette(p){return `<section class="brand-system"><div class="system-word" aria-label="Название бренда">${p.id==='alpakoff'?img('assets/alpakoff-logo.svg','Оригинальный логотип ALPAKOFF'):p.title.split(' / ')[0]}</div><div class="palette">${p.palette.map((c,i)=>`<div style="background:${c};color:${contrast(c)}"><span>0${i+1}</span><code>${c.toUpperCase()}</code></div>`).join('')}</div><div class="system-foot"><span>Визуальная система</span><span>Контраст · Масштаб · Ритм</span></div></section>`;}
function contrast(c){let n=c.replace('#','');let rgb=[0,2,4].map(i=>parseInt(n.slice(i,i+2),16));return rgb[0]*.299+rgb[1]*.587+rgb[2]*.114>145?'#171717':'#ffffff';}
function chapter(c,i){return `<section class="chapter reveal"><span class="chapter-index">${String(i+1).padStart(2,'0')}</span><div><h2>${c.title}</h2><p>${c.text}</p></div></section>`;}
function badges(){return `<section class="badge-section" id="diom-objects"><div class="shell"><div class="section-title"><h2>Айдентика.<br>В объёме.</h2><span class="eyebrow">Материал / Свет / 360°</span></div><div class="object-tabs" role="group" aria-label="3D-носитель">${[['badge','Пропуск на ленте']].map(([id,t],i)=>`<button data-object="${id}" aria-pressed="${i===0}">${t}</button>`).join('')}</div><div class="badge-stage"><canvas tabindex="0" aria-label="3D-носитель ДИОМ. Перетаскивайте для вращения или используйте стрелки."></canvas><img class="badge-fallback" src="${asset('assets/diom-elements/badge-source.webp')}" alt="Лицевая сторона пропуска ДИОМ" hidden><span class="badge-drag">Вращайте перетаскиванием</span><p class="badge-note">Объёмная адаптация оригинального бейджа. Графика лицевой стороны — по брендбуку; оборотная сторона — адаптация.</p></div><div class="badge-controls"><div role="group" aria-label="Цвет ленты" id="strap-controls">${['Оранжевый','Белый','Графит','Бирюза'].map((s,i)=>`<button data-strap="${i}" aria-pressed="${i===0}">${s}</button>`).join('')}</div><div><button id="badge-flip">Оборот ↻</button><button id="badge-reset">Сбросить</button><button id="badge-pause" aria-pressed="${reduced}">${reduced?'Автовращение':'Пауза'}</button></div><label>Отражения<input id="badge-gloss" type="range" min="0" max="1" step=".05" value=".85"></label><label id="foil-control" hidden><input id="badge-foil" type="checkbox"> Голографическая вставка</label></div></div></section>`;}
function bookReader(full=false){return `<section class="native-book" aria-label="Интерактивный брендбук ДИОМ"><header class="nb-head"><div><span class="eyebrow">ДИОМ / Brand system / 2026</span><h2>Инфраструктура<br>будущего.</h2></div><a href="${asset('assets/diom-brandbook.pdf')}" download="DIOM-Brandbook-2026.pdf">Исходный брендбук PDF ↓</a></header><nav class="nb-tabs" aria-label="Разделы брендбука">${['Знак','Цвет','Типографика','Система'].map((t,i)=>`<button data-nb-tab="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${t}</button>`).join('')}</nav><div class="nb-panel" data-nb-panel="0"><div class="nb-logo-stage" data-theme="light"><img class="nb-mark" src="${asset('assets/diom-mark.svg')}" alt="Векторный знак ДИОМ" width="320" height="320"><strong>ГКУ<br>ДИОМ</strong></div><div class="nb-controls"><div role="group" aria-label="Фон знака"><button data-nb-theme="light" aria-pressed="true">Светлый</button><button data-nb-theme="dark" aria-pressed="false">Графит</button><button data-nb-theme="orange" aria-pressed="false">Оранжевый</button></div><label><input id="nb-lockup" type="checkbox" checked> С подписью</label><a href="${asset('assets/diom-mark.svg')}" download="DIOM-logo.svg">Скачать SVG ↓</a></div><div class="nb-caption"><h3>Модуль, который объединяет.</h3><p>Геометрия знака строится на изометрическом модуле. В нём читаются объём, связь частей и архитектурная структура. Здесь используется исходный вектор с сайта ДИОМ.</p></div></div><div class="nb-panel" data-nb-panel="1" hidden><div class="nb-colors">${[['Construction orange','#FE5F27'],['Clean white','#FFFFFF'],['Concrete light','#A9A9A9'],['Urban grey','#565656'],['Dark graphite','#222220'],['DIOM blue','#6CB1B7']].map(([name,c])=>`<button data-copy-color="${c}" style="background:${c};color:${contrast(c)}"><span>${name}</span><strong>${c}</strong><small>Скопировать HEX</small></button>`).join('')}</div><p id="nb-copy-status" role="status">Нажмите на цвет, чтобы скопировать код.</p><div class="nb-caption"><h3>Оранжевый — действие.<br>Графит — структура.</h3><p>Основной акцент — Construction orange. Нейтральные цвета организуют информационные блоки, DIOM blue расширяет палитру. Названия и значения перенесены из брендбука.</p></div></div><div class="nb-panel" data-nb-panel="2" hidden><div class="nb-type-controls"><label>Ваш текст<input id="nb-type-input" type="text" maxlength="90" value="Создаём среду для будущего"></label><label>Масштаб<input id="nb-type-size" type="range" min="24" max="96" value="56"></label><label>Насыщенность<input id="nb-type-weight" type="range" min="200" max="900" step="100" value="700"></label></div><div class="nb-type-preview" id="nb-type-preview">Создаём среду для будущего</div><div class="nb-alphabet">АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ<br>abcdefghijklmnopqrstuvwxyz<br>0123456789</div><div class="nb-caption"><h3>Bounded</h3><p>Заголовочная гарнитура из брендбука. Живой образец использует настоящий вариативный шрифт: изменяйте текст, масштаб и насыщенность. Для наборного текста в исходной системе указан PT Root UI.</p></div></div><div class="nb-panel" data-nb-panel="3" hidden><div class="nb-layout"><div class="nb-layout-title"><img src="${asset('assets/diom-mark.svg')}" alt="" width="60" height="60"><span>ДИРЕКЦИЯ ИНФРАСТРУКТУРЫ<br>ОБРАЗОВАНИЯ МОСКВЫ</span></div><h3 id="nb-layout-text">Среда.<br>Образование.<br>Будущее.</h3><div class="nb-layout-bottom"><span>Город начинается<br>с возможностей.</span><span>diom.moscow</span></div></div><div class="nb-controls"><span>Исследование композиции</span><div role="group" aria-label="Тема плаката"><button data-layout-theme="orange" aria-pressed="true">Оранжевый</button><button data-layout-theme="dark" aria-pressed="false">Графит</button><button data-layout-theme="blue" aria-pressed="false">Бирюза</button></div></div><div class="nb-caption"><h3>Одна система.<br>Разные масштабы.</h3><p>Интерактивная композиция показывает работу знака, заголовка и служебного текста. Это развитие айдентики для портфолио: содержание набрано текстом, элементы остаются чёткими при увеличении.</p></div></div><div class="nb-end"><span>Айдентика в объёме</span><a class="text-link" href="${full?'#diom-objects':href('book')}">${full?'Перейти к носителям ↓':'Открыть брендбук и 3D-носители ↗︎'}</a></div></section>${full?badges():''}`;}
function alpakoffExperience(p){return `<section class="alp-editorial shell"><div class="alp-editorial-head"><span class="eyebrow">ALPAKOFF / Визуальная история</span><h2>Цвет.<br>Форма.<br><em>Присутствие.</em></h2><p>Цветы меняют настроение пространства. Важны жест, масштаб и свет — всё, что делает предмет частью жизни.</p></div><div class="alp-gallery">${p.gallery.map((x,i)=>`<figure><button data-alp-image="${x.image}" data-caption="Фотография ALPAKOFF ${i+1}" aria-label="Рассмотреть фотографию ${i+1}">${img(x.image,'Девушка с цветами — ALPAKOFF')}</button></figure>`).join('')}</div></section><section class="alp-brand-spread shell"><div class="alp-section-heading"><span class="eyebrow">02 / Предметный язык</span><h2>Бренд ощущается<br>в деталях.</h2><p>Матовая бумага, мягкий розовый, контрастная печать. Единая система для визитки, бирки, карточки и упаковки.</p></div>${img('assets/alpakoff-premium.webp','Концепция визиток, бирок и упаковочного рукава ALPAKOFF','alp-stationery')}<div class="alp-material-notes"><article><h3>Визитка</h3><p>Плотный хлопковый картон. Светлая и тёмная стороны связывают деловую коммуникацию с визуальным характером бренда.</p></article><article><h3>Бирка и карточка</h3><p>Небольшой формат, выразительный знак и свободное поле. Прикосновение к бренду продолжается после покупки.</p></article><article><h3>Упаковка</h3><p>Рукав для одного стебля и короб для композиции. Розовая бумага дополняет чёрный, сохраняя внимание на цветке.</p></article></div><p class="alp-concept-note">Концепция развития айдентики / предметные визуализации</p></section><section class="alp-original shell"><div class="alp-section-heading"><span class="eyebrow">03 / Digital</span><h2>Витрина<br>с характером.</h2><p>Развитие действующего магазина: оригинальный знак, фотографии ALPAKOFF и каталог как продолжение визуальной истории.</p></div><section class="alp-premium-details shell"><div><span class="eyebrow">Визитка / Контакт</span>${img('assets/alpakoff-logo.svg','ALPAKOFF')}<strong>alpakoff.ru</strong><p>Чёрная и розовая версии. Плотная фактурная бумага, лаконичный контакт на обороте.</p></div><div><span class="eyebrow">Премиальная упаковка</span><h3>Знак внимания.<br>До первого цветка.</h3><p>Жёсткая коробка с магнитным клапаном, розовая внутренняя отделка и тишью. Фирменная лента связывает коробку, букет и бирку в одну систему.</p><p>Ценник содержит название, артикул и стоимость; цена на визуализации приведена как пример оформления.</p></div></section><div class="alp-browser"><div class="alp-browser-bar"><span>ALPAKOFF — концепция страницы</span><a href="https://alpakoff.tilda.ws/" target="_blank" rel="noopener">Оригинальный сайт ↗︎</a></div><div class="alp-shop-nav">${img('assets/alpakoff-logo.svg','ALPAKOFF')}<span>Цветы и растения для ваших пространств</span></div><div class="alp-shop-hero"><div><span class="eyebrow">Искусство оставаться.</span><h3>Цветы.<br>Вне сезона.</h3><p>Для дома, проектов и красивых привычек.</p><a href="https://alpakoff.tilda.ws/" target="_blank" rel="noopener">Перейти в каталог ↗︎</a></div>${img('assets/alpakoff-real-flowers.webp','Цветочная композиция из действующего магазина ALPAKOFF')}</div><div class="alp-shop-bottom"><p>Один стебель.<br>Целое настроение.</p><span>Розница и опт<br>Сотрудничество с дизайнерами</span></div></div><div class="alp-original-actions"><button id="alp-site-open" aria-expanded="false">Посмотреть действующий магазин</button><a href="https://alpakoff.tilda.ws/" target="_blank" rel="noopener">alpakoff.tilda.ws ↗︎</a></div><div id="alp-live" hidden><div class="alp-live-bar"><span>alpakoff.tilda.ws</span><button id="alp-site-close">Свернуть ×</button></div><iframe id="alp-live-frame" title="Действующий магазин ALPAKOFF" loading="lazy" referrerpolicy="no-referrer" sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox"></iframe></div></section>`;}
function alpakoffPage(p){return `<main class="case-page case-alpakoff" style="--case-bg:#f7f7f5;--case-fg:#111111;--case-accent:#daa3a5"><section class="case-head shell"><div class="case-top"><a href="${href('work')}">← Все работы</a><span class="eyebrow">Собственный бизнес / Концепция развития</span></div><h1 tabindex="-1"><img src="${asset('assets/alpakoff/logo.svg')}" alt="ALPAKOFF" class="alpakoff-heading"  width="1536" height="1024"></h1><div class="case-lead"><p>Цветы как часть пространства.</p><span>Бренд · Упаковка · Digital</span></div></section><div class="case-hero-image"><img src="${asset('assets/alpakoff/hero.webp')}" alt="Розовые каллы в металлическом кашпо с логотипом ALPAKOFF" class=""  width="1536" height="1024"></div><div class="a5">
<section class="wrap brief"><span class="kicker">01 / Арт-дирекшн</span><div><h2>Цвет. Форма.<br><em>Присутствие.</em></h2><p>Цветы, которые меняют ощущение пространства. Мягкая пластика лепестков, строгая геометрия знака и отражающий металл — три опоры новой визуальной концепции ALPAKOFF.</p><p class="note">Собственный бизнес Артёма Кречетова · Концепция развития бренда</p></div></section>
<section class="wrap identity"><div class="section-head"><span class="kicker">02 / Система бренда</span><h2>Узнаваемость<br>в каждом касании.</h2></div><div class="identity-grid"><div class="brand-sign"><img src="${asset('assets/alpakoff/logo.svg')}" alt="ALPAKOFF" ><span>Оригинальный знак / геометрия и разделитель</span></div><div class="identity-copy"><h3>Строгий знак. Мягкий акцент.</h3><p>Широкие пропорции логотипа задают устойчивость. Разделитель перед OFF становится принципом композиции: разделяет изображение и информацию, оставляя каждому своё место.</p><p>Розовый взят из фирменной палитры. Он появляется в упаковке и отдельных акцентах, а фотографии сохраняют естественные цвета.</p></div></div><div class="palette"><article style="--swatch:#000000"><i></i><b>Чёрный</b><code>#000000</code><p>Знак, контраст, сценография.</p></article><article style="--swatch:#ffffff"><i></i><b>Белый</b><code>#FFFFFF</code><p>Каталог, бумага, ясная информация.</p></article><article style="--swatch:#daa3a5"><i></i><b>Фирменный розовый</b><code>#DAA3A5</code><p>Упаковка и точечные акценты.</p></article><article style="--swatch:#525252"><i></i><b>Нейтральный серый</b><code>#525252</code><p>Второстепенный текст на светлом фоне.</p></article></div></section>
<section class="campaign wrap"><div class="section-head"><span class="kicker">03 / Фотографический язык</span><h2>Характер —<br>в живом жесте.</h2></div><div class="campaign-grid"><figure class="portrait"><img src="${asset('assets/alpakoff/campaign-portrait.webp')}" alt="Фотография ALPAKOFF: девушка рядом с интерьерной стрелицией" loading="lazy"><span class="campaign-logo"><img src="${asset('assets/alpakoff/logo.svg')}" alt="ALPAKOFF" ></span></figure><figure class="detail"><img src="${asset('assets/alpakoff/campaign-detail.webp')}" alt="Фотография ALPAKOFF: розовый цветок, деталь" loading="lazy"><figcaption><span>Силуэт / Фактура / Масштаб</span><p>Общий план показывает характер композиции. Крупный — форму лепестка и качество материала. Исходные фотографии бренда сохраняют свою естественную фактуру.</p></figcaption></figure></div></section>
<section class="pack wrap"><div class="section-head"><span class="kicker">04 / Упаковка</span><h2>Продолжение<br>впечатления.</h2></div><div class="pack-grid"><figure><img src="${asset('assets/alpakoff/pack.webp')}" alt="Коробка ALPAKOFF и большой глянцевый каталог на русском с двумя разными девушками и коллекцией цветов" loading="lazy"></figure><div class="pack-copy"><h3>Сначала — прикосновение.</h3><p>Жёсткая коробка защищает композицию. Внутри — тонкая бумага; снаружи — исходный знак и ровная лента. Большой глянцевый каталог знакомит с коллекцией: две героини фотосъёмки, разные виды цветов, подписи на русском и аккуратная журнальная вёрстка.</p><dl><div><dt>Коробка</dt><dd>Матовая бумага, деликатное тиснение</dd></div><div><dt>Каталог</dt><dd>Фотографии коллекции и детали композиций</dd></div><div><dt>Визитка</dt><dd>Плотная чёрная бумага, тиснение знака · alpakoff.ru</dd></div><div><dt>Бирка</dt><dd>Название, артикул и рекомендации</dd></div></dl><span class="note">Предметная визуализация концепции</span></div></div></section>
<section class="digital wrap" id="catalog"><div class="section-head"><span class="kicker">05 / Digital</span><h2>Коллекция.<br>Без лишних жестов.</h2><p>Фотографии и товары действующего магазина — в выровненной сетке. Полные названия и единая линия действий помогают спокойно сравнивать композиции.</p></div><div class="laptop"><div class="screen"><div class="shop-head"><img src="${asset('assets/alpakoff/logo.svg')}" alt="ALPAKOFF" ><a href="https://alpakoff.tilda.ws/catalog" target="_blank" rel="noopener">Магазин ↗︎</a></div><div class="shop-bar"><span>Каталог / Цветущие</span><span>ALPAKOFF COLLECTION</span></div><div class="products"><article class="product"><div class="product-photo"><img src="${asset('assets/alpakoff/product-ranunculus.webp')}" alt="Ранункулус Декоративный БЕЛЫЙ, 1 ветка - 52 см" ></div><h4>Ранункулус Декоративный БЕЛЫЙ, 1 ветка - 52 см</h4><p class="price">640 ₽</p><div class="product-actions"><a href="https://alpakoff.ru/tproduct/597844136-190110075051-ranunkulus-dekorativnii-belii-1-vetka-52" target="_blank" rel="noopener">Подробнее ↗︎</a></div></article><article class="product"><div class="product-photo"><img src="${asset('assets/alpakoff/product-lavender.webp')}" alt="Лаванда Декоративная, 1 ветка - 40 см" ></div><h4>Лаванда Декоративная, 1 ветка - 40 см</h4><p class="price">460 ₽</p><div class="product-actions"><a href="https://alpakoff.ru/catalog/tproduct/595141084-564135582671-lavanda-dekorativnaya-1-vetka-40-sm" target="_blank" rel="noopener">Подробнее ↗︎</a></div></article><article class="product"><div class="product-photo"><img src="${asset('assets/alpakoff/product-rose.webp')}" alt="Роза Кустовая БЕЛАЯ, 1 ветка - 75 см" ></div><h4>Роза Кустовая БЕЛАЯ, 1 ветка - 75 см</h4><p class="price">670 ₽</p><div class="product-actions"><a href="https://alpakoff.ru/catalog/tproduct/595141084-943342455081-roza-kustovaya-belaya-1-vetka-75-sm" target="_blank" rel="noopener">Подробнее ↗︎</a></div></article><article class="product"><div class="product-photo"><img src="${asset('assets/alpakoff/product-peony.webp')}" alt="Пион Декоративный БЕЛО-РОЗОВЫЙ, 1 ветка - 90 см" ></div><h4>Пион Декоративный БЕЛО-РОЗОВЫЙ, 1 ветка - 90 см</h4><p class="price">940 ₽</p><div class="product-actions"><a href="https://alpakoff.ru/catalog/tproduct/595141084-573358222071-pion-dekorativnii-belo-rozovii-1-vetka-9" target="_blank" rel="noopener">Подробнее ↗︎</a></div></article></div></div><div class="laptop-base"></div></div><div class="digital-foot"><span>Адаптация каталога для кейса · Товары с сайта ALPAKOFF</span><a class="action" href="https://alpakoff.tilda.ws/catalog" target="_blank" rel="noopener">Открыть весь каталог ↗︎</a></div></section>
<section class="retail wrap"><div class="section-head"><span class="kicker">06 / Пространство бренда</span><h2>Цветочная<br>сценография.</h2><p>Выставочный стенд продолжает образ первой композиции: металл, направленный свет и цветы в центре внимания.</p></div><figure class="retail-stage"><img src="${asset('assets/alpakoff/retail-stage.webp')}" alt="Новая концепция выставочного стенда ALPAKOFF: металлические модули, искусственные деревья, цветы и зона упаковки" loading="lazy"></figure><div class="retail-notes"><p><b>01 / Увидеть</b>Центральная композиция показывает готовое интерьерное решение.</p><p><b>02 / Выбрать</b>Искусственные деревья, гортензии, пионы, лаванда и декоративные ветки разделены по модулям. Бирки размещаются рядом.</p><p><b>03 / Забрать</b>Упаковка и запас материалов находятся под рабочей поверхностью.</p></div><span class="note">Авторская визуализация. Размеры и конструкция адаптируются под магазин.</span></section>
<section class="wrap photo-series" aria-label="Фотографии коллекции ALPAKOFF"><div class="section-head"><span class="kicker">07 / Фотосерия</span><h2>Разные цветы.<br>Разное настроение.</h2></div><div class="photo-series-grid"><figure><img src="${asset('assets/alpakoff/series-blue.webp')}" alt="Девушка с голубыми декоративными ветками ALPAKOFF" loading="lazy"></figure><figure><img src="${asset('assets/alpakoff/series-roses.webp')}" alt="Девушка с белыми розами на оранжевом фоне — ALPAKOFF" loading="lazy"></figure></div></section>
<footer class="wrap finale" id="contact"><div><img src="${asset('assets/alpakoff/logo.svg')}" alt="ALPAKOFF" ><p>Цветы как часть пространства.</p></div><a class="action" href="${href('work')}">Все проекты ↗︎</a><button id="motion" type="button" aria-pressed="false">Пауза движения</button><a href="#">Наверх ↑</a></footer></div></main>`;}
function diomIdentity(){return `<section class="diom-live-identity shell" aria-label="Айдентика ДИОМ"><div class="diom-type-tile"><span class="eyebrow">Дирекция инфраструктуры образования Москвы</span><h2>СТРОИМ<br><span>СРЕДУ.</span><br>СОЗДАЁМ<br>БУДУЩЕЕ.</h2><p>Визуальная система городской институции</p></div><div class="diom-logo-tile">${img('assets/diom-mark.svg','Оригинальный знак ДИОМ')}<strong>ГКУ ДИОМ</strong><span>Москва / Айдентика</span></div><div class="diom-links-tile"><span class="eyebrow">Цифровая среда</span><a href="#diom-part-7">Сайт и сервисы ↗︎</a><a href="#diom-part-11">Образовательные объекты ↗︎</a></div><div class="diom-word-tile"><strong>ДИРЕКЦИЯ</strong><span>ИНФРАСТРУКТУРЫ</span><strong>ОБРАЗОВАНИЯ</strong><span>МОСКВЫ</span></div><div class="diom-color-tile"><span>#FE5F27</span><strong>Construction<br>orange</strong></div><div class="diom-site-tile">${img('assets/diom-site.webp','Сайт ДИОМ на компьютере, планшете и телефоне')}</div><div class="diom-paper-tile">${img('assets/brand-stationery.webp','Визитки, бланки и фирменные носители ДИОМ')}</div><div class="diom-type-specimen"><span class="eyebrow">Типографика / Bounded</span><strong>Аа Бб Вв</strong><p>Геометрия знака. Масштаб текста.<br>Одна система на разных носителях.</p></div></section>`;}

function special(p){if(p.demo==='digital')return `<section class="digital-section"><div class="shell"><span class="eyebrow">Цифровая экосистема</span><h2>Сайт.<br><em>Конструктор. Процессы.</em></h2><div class="digital-grid"><a href="https://diom.moscow/" target="_blank" rel="noopener"><strong>01</strong><h3>Официальный сайт</h3><p>Структура, интерфейс и единая визуальная система.</p><span>Открыть diom.moscow ↗︎</span></a><a href="https://diom.moscow/game" target="_blank" rel="noopener"><strong>02</strong><h3>School Builder</h3><p>Четыре типа помещений. Расстановка предметов, цвет стен и управление камерой.</p><span>Открыть игру ↗︎</span></a><div><strong>03</strong><h3>Внутренние решения</h3><p>Заявки, согласования, данные и отчётность. Python, Bitrix24 и веб-разработка.</p><span>Опыт из резюме</span></div></div></div></section>`;
if(p.demo==='schools')return `<section class="school-system shell"><span class="eyebrow">Четыре сценария среды</span><div class="school-tabs" role="group" aria-label="Тип пространства">${['Учиться','Общаться','Исследовать','Выступать'].map((x,i)=>`<button data-school="${i}" aria-pressed="${i===0}">${x}</button>`).join('')}</div><div class="school-panel"><span id="school-num">01</span><div><h2 id="school-title">Учебный кабинет</h2><p id="school-text">Спокойный фон, ясная организация рабочих мест и визуальные акценты, которые поддерживают внимание.</p></div></div><a class="text-link" href="https://diom.moscow/reconstruction" target="_blank" rel="noopener">Программа реконструкции на сайте ДИОМ ↗︎</a><a class="text-link" href="https://diom.moscow/standart" target="_blank" rel="noopener">Стандарт школьной среды ↗︎</a></section>`;
if(p.demo==='shop')return alpakoffExperience(p)+`<section class="shop-demo shell">${img('assets/alpakoff-logo.svg','ALPAKOFF','shop-brand')}<div class="demo-label">Искусственные цветы и интерьерные решения</div><div class="shop-title"><h2>Природа формы.<br><em>Без срока цветения.</em></h2><span>Objects that stay.</span></div><div class="shop-filters" role="group" aria-label="Категория каталога"><button data-shop="all" aria-pressed="true">Всё</button><button data-shop="stems" aria-pressed="false">Стебли</button><button data-shop="sets" aria-pressed="false">Композиции</button></div><div class="shop-products"><article data-category="stems">${img(p.images[0],'Фото композиции с сайта ALPAKOFF')}<div><h3>Один выразительный акцент</h3><span>Стебли / направление коллекции</span></div></article><article data-category="sets">${img(p.images[1],'Упаковка и композиция ALPAKOFF')}<div><h3>Композиция для пространства</h3><span>Наборы / направление коллекции</span></div></article></div><p class="demo-note">Интерфейсная демонстрация нового направления. Изображения не являются карточками действующего товарного каталога. <a href="https://alpakoff.tilda.ws/" target="_blank" rel="noopener">Посмотреть действующий магазин ↗︎</a></p></section>`;
if(p.demo==='mono')return `<section class="mono-demo"><div class="shell"><div class="demo-label">MONO / Product experience</div><h2 id="mono-title">Слышать.<br><em>Чувствовать.</em></h2><div class="mono-frame">${img(p.images[0],'MONO — концепция акустики','',false)}</div><div class="mono-controls" role="group" aria-label="Режим просмотра устройства"><button data-mono="0" aria-pressed="true">Форма</button><button data-mono="1" aria-pressed="false">Исследование</button></div><p id="mono-caption">Металл, акустическая ткань и точная пропорция.</p><span class="demo-note">Работающий прототип промостраницы вымышленного продукта.</span></div></section>`;
if(p.demo==='index')return `<section class="data-demo shell"><div class="demo-label">INDEX / Демонстрационные данные</div><div class="data-head"><h2>Портфель проектов</h2><span>Обзор / Условный сценарий</span></div><div class="data-kpis"><div><span>Всего проектов</span><strong>06</strong></div><div><span>В работе</span><strong>03</strong></div><div><span>Требуют внимания</span><strong>01</strong></div></div><div class="data-filters" role="group" aria-label="Статус проектов"><button data-status="all" aria-pressed="true">Все</button><button data-status="active" aria-pressed="false">В работе</button><button data-status="attention" aria-pressed="false">Внимание</button><button data-status="done" aria-pressed="false">Завершены</button></div><div class="data-table"><table><thead><tr><th>Объект</th><th>Состояние</th><th>Готовность</th></tr></thead><tbody>${[['Северный квартал','active','В работе',72],['Общественный центр','attention','Внимание',38],['Городская библиотека','done','Завершён',100],['Южный кампус','active','В работе',64],['Выставочное пространство','active','В работе',48],['Двор у реки','done','Завершён',100]].map(([name,state,label,n])=>`<tr data-state="${state}"><td>${name}</td><td><span class="data-state ${state}">${label}</span></td><td><div class="bar"><span style="width:${n}%"></span></div>${n}%</td></tr>`).join('')}</tbody></table></div><p class="demo-note">Все названия и значения вымышлены. Фильтры показывают поведение интерфейса.</p></section>`;return '';}
function diomBrandbookSection(b){const n=b.page;let body='';const lock=`<div class="diom-lockup">${img('assets/diom-mark.svg','Знак ДИОМ')}<strong>ГКУ<br>ДИОМ</strong></div>`;if([1,3,32].includes(n))body=`<div class="diom-brand-cover ${n===32?'is-blue':''}">${lock}${n===1?'<span>Брендбук / 2026</span>':''}</div>`;else if(n===2)body=`<div class="diom-evolution"><div><span>Было</span>${img(b.images[0],'Предыдущий логотип Дирекции')}</div><div><span>Стало</span>${lock}</div></div>`;else if(n===5)body=`<div class="diom-lockups">${['white','orange','dark','blue'].map(c=>`<div class="lockup-${c}">${lock}</div>`).join('')}</div>`;else if(n===6)body=`<div class="diom-fonts"><div><span>Заголовочный шрифт</span><strong>Bounded</strong><p>АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЪЫЬЭЮЯ<br>абвгдеёжзийклмнопрстуфхцчшщъыьэюя<br>1234567890</p></div><div><span>Наборный шрифт</span><h3>PT Root UI</h3><p>Ясная структура. Удобное чтение.<br>Интерфейсы и документация.</p></div></div><div class="diom-full-palette">${[['#FE5F27','Construction orange'],['#FFFFFF','Clean white'],['#A9A9A9','Concrete light'],['#565656','Urban grey'],['#222220','Dark graphite'],['#6CB1B7','DIOM blue']].map(([c,t])=>`<div style="background:${c};color:${contrast(c)}"><strong>${t}</strong><code>${c}</code></div>`).join('')}</div>`;else if(n===8)body=diomIdentity();else if(n===14)body=`<div class="diom-badge-source">${img('assets/diom-elements/badge-source.webp','Оригинальный макет бейджа из брендбука')}<div><h3>Один пропуск.<br>Четыре ленты.</h3><p>Графика и компоновка — по исходному брендбуку. Объёмный просмотр находится здесь же, ниже.</p><div class="diom-strap-samples">${[0,1,2,3].map(i=>img('assets/strap-'+i+'.webp','Фирменная лента '+(i+1))).join('')}</div></div></div>${badges()}`;else if(n===11||n===12)body=`<div class="diom-school-states"><div class="diom-school-stage" data-state="idle">${img(b.images[0],'Статичная изометрия школьного объекта','school-idle')}${img(b.images[1],'Активная изометрия школьного объекта','school-active')}</div><div class="school-switch" role="group" aria-label="Состояние изометрии"><span>${n===11?'Большой Факельный переулок':'Самолётик / 65-426/1'}</span><button data-school-state="idle" aria-pressed="true">Обычный вид</button><button data-school-state="active" aria-pressed="false">Цветовой акцент</button></div></div>`;else body=`<div class="diom-object-gallery ${b.images.length===1?'single':''}">${b.images.map((x,i)=>img(x,b.title+' — исходный макет '+(i+1))).join('')}</div>`;return `<section class="diom-book-section" id="diom-part-${n}"><div class="diom-part-heading"><span>${String(n).padStart(2,'0')} / 32</span><h2>${b.title}</h2><p>${b.text}</p></div>${body}</section>`;}
function kititPage(p){const i=projects.indexOf(p),next=projects[(i+1)%projects.length];return `<main class="case-page case-kitit" style="--case-bg:#f5f2ea;--case-fg:#252522;padding-top:0"><div class="kitit-host"></div><a class="next-project" href="${href(next.id)}"><span class="eyebrow">Следующий проект</span><strong>${next.title}</strong><span>↗︎</span></a></main>${footer()}`;}
